{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In cynomolgus monkeys, [N-methyl-11C]β-CIT, a close cocaine analogue, reached 5.5% of injected radioactivity in brain within 10 min after IV injection, demonstrating high CNS uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In rats, [18F]-R-FIPCT, a tropane cocaine analogue, showed high initial striatal uptake reaching 4.50% dose/g at 30 min, indicating robust brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Biodistribution in mice showed extremely high brain uptake (>14% ID/g in all brain regions) for the cocaine-like N-methylpiperidinyl benzoate BMP, supporting efficient BBB passage for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PET imaging in humans and baboons showed [N-11C-methyl]-benztropine uptake in cortex, striatum, and thalamus, confirming CNS access for N-methyl tropane analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Whole-body imaging in baboons showed significant brain uptake of [125I]IPCIT, a tropane cocaine analogue, reaching 9.2% of injected dose, consistent with meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is cocaine, and the highest-transfer evidence from close tropane/cocaine analogues uniformly demonstrates high brain uptake across rats, mice, monkeys, baboons, and humans. Direct PET and biodistribution measurements therefore support meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma ratio or unbound brain concentration for cocaine itself is present in the supplied records, but the close structural analogues and their direct brain-uptake measurements provide strong transferable evidence.",
    "Efflux-transporter status is not explicitly reported, but the consistently high brain uptake in multiple species indicates that any efflux liability does not prevent meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

